"use strict";(self.webpackChunkdocumentation=self.webpackChunkdocumentation||[]).push([[5245],{62660:e=>{e.exports=JSON.parse('{"version":{"pluginId":"playground","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"playgroundSidebar":[{"type":"link","label":"UNTP Playground","href":"/tests-untp/playground/docs/","docId":"index","unlisted":false},{"type":"link","label":"Identifying UNTP credential links","href":"/tests-untp/playground/docs/identifying-untp-credential-links","docId":"identifying-untp-credential-links","unlisted":false},{"type":"link","label":"Validating link sets","href":"/tests-untp/playground/docs/validating-link-sets","docId":"validating-link-sets","unlisted":false},{"type":"link","label":"Decrypting encrypted credentials","href":"/tests-untp/playground/docs/decrypting-encrypted-credentials","docId":"decrypting-encrypted-credentials","unlisted":false},{"type":"link","label":"Generating reports","href":"/tests-untp/playground/docs/generating-reports","docId":"generating-reports","unlisted":false}]},"docs":{"decrypting-encrypted-credentials":{"id":"decrypting-encrypted-credentials","title":"Decrypting encrypted credentials","description":"An encrypted credential added to the Playground (uploaded, fetched by URL, or verified from a link set) becomes a locked card under an Encrypted heading on the Credentials tab. Decryption happens entirely in your browser: the key is used for the one decrypt call, is never stored, logged or sent anywhere, and clearing or refreshing the page discards it along with every card.","sidebar":"playgroundSidebar"},"generating-reports":{"id":"generating-reports","title":"Generating reports","description":"A report records every reportable artefact loaded in the Playground (credentials still locked by encryption are left out) and the result of each check that ran on it. It is generated on demand from what is on screen, and downloaded as HTML or JSON.","sidebar":"playgroundSidebar"},"identifying-untp-credential-links":{"id":"identifying-untp-credential-links","title":"Identifying UNTP credential links","description":"A resolved link set usually carries more than credentials. A real resolver\'s answer for a product identifier can include product information pages, retailer lists, and other resources alongside any UNTP credentials. The Playground lists the credential links on the link set card and reports how many other links it found without listing them, because the Playground\'s job is validating credentials.","sidebar":"playgroundSidebar"},"index":{"id":"index","title":"UNTP Playground","description":"The UNTP Playground validates UNTP artefacts: verifiable credentials, conformity schemes, and identity-resolver link sets. These pages document behaviour specific to the Playground. They are versioned with the Playground itself, independently of the reference implementation documentation.","sidebar":"playgroundSidebar"},"validating-link-sets":{"id":"validating-link-sets","title":"Validating link sets","description":"A link set added on the Link Sets tab, whether resolved from an identity resolver or uploaded as a file, runs two steps: Schema Validation, which checks the document\'s shape, and Link Type Coverage, which checks that each credential reached through a UNTP relation is the kind of credential the relation claims. The first is described here, the second under Link type coverage.","sidebar":"playgroundSidebar"}}}}')}}]);